<?php
require_once __DIR__ . '/_friend_helpers.php';
try { if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $d=friends_input(); $c=friends_connection(); if(!SessionHelper::isAuthenticated()){ApiResponse::unauthorized();exit;} if(!friends_require_active($c)){ApiResponse::forbidden('Active account required.');exit;} if(!friends_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} $uid=SessionHelper::getUserId(); $target=(int)($d['user_id']??0); if($target<=0||$target===$uid||!friends_active($c,$target)){ApiResponse::validation(['user_id'=>'Invalid user.']);exit;} $c->beginTransaction(); $c->prepare("UPDATE friend_requests SET status='blocked', responded_at=NOW() WHERE (sender_id=:a AND receiver_id=:b) OR (sender_id=:b AND receiver_id=:a)")->execute(['a'=>$uid,'b'=>$target]); $c->prepare("INSERT INTO friendships (user_id,friend_id,status) VALUES (:a,:b,'blocked') ON DUPLICATE KEY UPDATE status='blocked'")->execute(['a'=>$uid,'b'=>$target]); $c->prepare("INSERT INTO friendships (user_id,friend_id,status) VALUES (:b,:a,'blocked') ON DUPLICATE KEY UPDATE status='blocked'")->execute(['a'=>$uid,'b'=>$target]); $c->commit(); ApiResponse::success([],'User blocked.'); } catch(Throwable $e){ if(isset($c)&&$c->inTransaction())$c->rollBack(); Logger::error('Friend block failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to block user.');}
?>
